export type ParsedInitEscrowInstruction<
  TProgram extends string = typeof AESDR_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    buyer: TAccountMetas[0];
    seller: TAccountMetas[1];
    arbiter: TAccountMetas[2];
    escrow: TAccountMetas[3];
    /** Lamport vault. Must NOT be an existing populated account. */
    vault: TAccountMetas[4];
    bond: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: InitEscrowInstructionData;
};

export function parseInitEscrowInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedInitEscrowInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      buyer: getNextAccount(),
      seller: getNextAccount(),
      arbiter: getNextAccount(),
      escrow: getNextAccount(),
      vault: getNextAccount(),
      bond: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getInitEscrowInstructionDataDecoder().decode(instruction.data),
  };
}
